<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, mutate, session } from '../../shared/api'
import { showError, toast } from '../../shared/state'
import type { Notification, Snapshot, Todos } from '../../shared/types'
import { dateTime, money, feeNames } from '../../shared/format'
import Icon from '../../shared/Icon.vue'
import Modal from '../../shared/Modal.vue'
import Badge from '../../shared/Badge.vue'
import QuotePanel from '../../shared/QuotePanel.vue'
import OrdersView from '../orders/OrdersView.vue'
const linkedOrderId = ref('')
const notices = ref<Notification[]>([]), todos = ref<Todos>(), busy = ref(false), loading = ref(false), tab = ref('todo')
const count = computed(() => todos.value ? todos.value.approvals.length + todos.value.extensions.length + todos.value.fees.length + todos.value.relocations.length + todos.value.workItems.length : 0)
const preview = ref<{snapshot: Snapshot; action?: string; id?: string}>(), accepted = ref(false)
const contact = ref<{id: string; kind: string}>(), reason = ref(''), contacts = ref<{name: string; phone: string}[]>([])
const workId = ref(''), workNote = ref('')
async function load(silent = false) { if (!silent) loading.value = true; try { const [n, t] = await Promise.all([api<Notification[]>('/notifications'), api<Todos>('/todos')]); notices.value = n; todos.value = t } catch (e) { showError(e) } finally { if (!silent) loading.value = false } }
onMounted(() => load())
async function read(n: Notification) { if (!n.isRead) { try { const result = await mutate(`/notifications/${n.id}/read`); if (result.status !== 'SUCCEEDED') { toast(result.message, true); return }; n.isRead = true } catch (e) { showError(e); return } } if (n.orderId) linkedOrderId.value = n.orderId }
async function closeLinkedOrder() { linkedOrderId.value = ''; await load(true) }
async function view(quoteId: string, action?: string, id?: string) { try { const q = await api<{snapshot: Snapshot}>('/quotes/' + quoteId); preview.value = {snapshot: q.snapshot, action, id}; accepted.value = false } catch (e) { showError(e) } }
async function confirm() { if (!preview.value?.action || !preview.value.id) return; busy.value = true; try { const p = preview.value; const r = await mutate(p.action === 'extension' ? `/extensions/${p.id}/confirmations` : `/change-approvals/${p.id}/confirmations`, {priceConfirmed: accepted.value}); toast(r.message); if (r.status === 'SUCCEEDED') { preview.value = undefined; await load() } } catch (e) { showError(e) } finally { busy.value = false } }
async function retry(id: string) { busy.value = true; try { const r = await mutate(`/notification-tasks/${id}/retry`); toast(r.message); await load() } catch (e) { showError(e) } finally { busy.value = false } }
function contactDialog(id: string, kind: string) { contact.value = {id, kind}; reason.value = ''; contacts.value = [] }
async function accessContact() { if (!contact.value) return; busy.value = true; try { const r = await api<{contacts: {name: string; phone: string}[]}>('/admin/contact-accesses', {method: 'POST', body: JSON.stringify({exceptionId: contact.value.id, exceptionType: contact.value.kind, reason: reason.value})}); contacts.value = r.contacts; toast('本次完整号码查看的原因与时间已记录') } catch (e) { showError(e) } finally { busy.value = false } }
async function resolveWork() { busy.value = true; try { const r = await mutate(`/work-items/${workId.value}/resolution`, {note: workNote.value}); toast(r.message); if (r.status === 'SUCCEEDED') { workId.value = ''; await load() } } catch (e) { showError(e) } finally { busy.value = false } }
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">NOTIFICATIONS & TASKS</span><h1>通知与待办</h1><p>跟进相关订单、共同确认、费用核对和通知发送异常。</p></div><button class="button secondary" @click="load()"><Icon name="refresh" :size="17"/>刷新</button></div>
  <section class="card"><div class="admin-tabs"><button :class="{active: tab === 'todo'}" @click="tab = 'todo'">业务待办 <span class="tab-count">{{ count }}</span></button><button :class="{active: tab === 'notices'}" @click="tab = 'notices'">站内通知 <span class="tab-count">{{ notices.filter(n => !n.isRead).length }}</span></button><button v-if="session.user?.role === 'ADMIN'" :class="{active: tab === 'failed'}" @click="tab = 'failed'">发送失败跟进 <span class="tab-count">{{ todos?.failedTasks.length || 0 }}</span></button></div><div v-if="loading" class="empty-state">正在读取通知与待办…</div>
    <template v-else-if="tab === 'todo'"><div v-if="!count" class="empty-state"><Icon name="check" :size="36"/><h3>当前没有待处理事项</h3><p>与您有关的确认和异常会显示在这里。</p></div><article v-for="a in todos?.approvals" :key="a.id" class="task-card"><span class="task-symbol"><Icon name="shield"/></span><div class="task-content"><h3>特殊改订共同确认</h3><p>{{ a.orderCode }} · 管理员 {{ a.adminId ? '已确认' : '待确认' }} / 酒店 {{ a.hotelUserId ? '已确认' : '待确认' }}</p></div><button class="text-button" @click="linkedOrderId = a.orderId">查看订单</button><button class="button secondary" @click="view(a.quoteId, ((session.user?.role === 'ADMIN' && !a.adminId) || (session.user?.role === 'HOTEL' && !a.hotelUserId)) ? 'approval' : undefined, a.id)">{{ session.user?.role === 'RECEPTION' ? '查看指定方案' : '核对方案与确认' }}</button></article><article v-for="e in todos?.extensions" :key="e.id" class="task-card"><span class="task-symbol green-tone"><Icon name="calendar"/></span><div class="task-content"><h3>续住日期及价格确认</h3><p>{{ e.orderCode }} · 新增日期尚未占用名额</p></div><button class="text-button" @click="linkedOrderId = e.orderId">查看订单</button><button class="button secondary" @click="view(e.quoteId, session.user?.role === 'RECEPTION' ? 'extension' : undefined, e.id)">查看新增报价</button></article><article v-for="f in todos?.fees" :key="f.id" class="task-card"><span class="task-symbol amber-tone"><Icon name="log"/></span><div class="task-content"><h3>{{ feeNames[f.category] }} · ¥ {{ money(f.amount) }}</h3><p>{{ f.orderCode }} · {{ f.note }}</p></div><Badge :status="f.status"/><button v-if="session.user?.role === 'ADMIN' && f.status === 'DISPUTED'" class="text-button" @click="contactDialog(f.id, 'FEE')">异常联系方式</button><button class="button secondary" @click="linkedOrderId = f.orderId">查看与处理</button></article><article v-for="c in todos?.relocations" :key="c.id" class="task-card"><span class="task-symbol amber-tone"><Icon name="building"/></span><div class="task-content"><h3>停业住宿待安置</h3><p>{{ c.orderCode }} · 原订单与占用暂时保留</p></div><button v-if="session.user?.role === 'ADMIN'" class="text-button" @click="contactDialog(c.id, 'RELOCATION')">异常联系方式</button><button class="button primary" @click="linkedOrderId = c.orderId">{{ session.user?.role === 'RECEPTION' ? '选择替代方案' : '查看安置进度' }}</button></article><article v-for="w in todos?.workItems" :key="w.id" class="task-card"><span class="task-symbol amber-tone"><Icon name="info"/></span><div class="task-content"><h3>{{ w.title }}</h3><p>{{ w.detail }}</p></div><button v-if="session.user?.role === 'ADMIN'" class="button secondary" @click="workId = w.id; workNote = ''">记录人工跟进</button></article></template>
    <template v-else-if="tab === 'notices'"><div v-if="!notices.length" class="empty-state"><Icon name="bell" :size="36"/><h3>暂无站内通知</h3><p>通知会在业务提交后发送，不影响已生效的订单。</p></div><article v-for="n in notices" :key="n.id" class="notification-row" :class="{unread: !n.isRead}"><span class="notification-dot"></span><div><h3>{{ n.title }}</h3><p>{{ n.body }}</p><small class="muted">{{ dateTime(n.createdAt) }}</small></div><button class="text-button" @click="read(n)">{{ n.orderId ? '查看相关订单' : n.isRead ? '已读' : '标记已读' }}</button></article></template>
    <template v-else><div class="notice warning"><Icon name="info"/><span>失败通知不会撤销已提交业务。重新发送前请核实学校邮箱与邮件服务配置，发送成功也不等于接收人已阅读。</span></div><div v-if="!todos?.failedTasks.length" class="empty-state"><h3>没有发送失败任务</h3></div><article v-for="t in todos?.failedTasks" :key="t.id" class="task-card"><span class="task-symbol amber-tone"><Icon name="bell"/></span><div class="task-content"><h3>{{ t.title }} · {{ t.channel === 'EMAIL' ? '学校邮件' : '站内通知' }}</h3><p>{{ t.lastError }} · 已尝试 {{ t.attempts }} 次</p><small class="muted">下次尝试时间 {{ dateTime(t.nextAttemptAt) }}</small></div><Badge :status="t.status"/><button class="button secondary" :disabled="busy" @click="retry(t.id)">修复后重试</button></article></template>
  </section>
  <Modal v-if="preview" :title="preview.action === 'extension' ? '核对并确认续住报价' : '核对指定方案'" wide @close="preview = undefined"><QuotePanel :snapshot="preview.snapshot"/><label v-if="preview.action" class="check-line"><input v-model="accepted" type="checkbox"/>已核对该方案的日期、逐晚价格及适用规则。</label><template #footer><button class="button secondary" @click="preview = undefined">返回</button><button v-if="preview.action" class="button primary" :disabled="!accepted || busy" @click="confirm">{{ preview.action === 'extension' ? '确认续住生效' : '确认本方意见' }}</button></template></Modal>
  <Modal v-if="contact" title="异常处理：受控查看完整联系方式" @close="contact = undefined; contacts = []"><div class="notice">管理员默认查看脱敏号码。请说明当前具体异常的处理原因，本次查看的原因与时间会被记录。</div><form v-if="!contacts.length" id="contact-form" class="form-stack" @submit.prevent="accessContact"><label>查看原因<textarea v-model="reason" required maxlength="500"/></label></form><div v-else class="contact-list"><div v-for="c in contacts" :key="c.phone" class="detail-row"><strong>{{ c.name }}</strong><a :href="'tel:' + c.phone">{{ c.phone }}</a></div></div><template #footer><button class="button secondary" @click="contact = undefined; contacts = []">关闭</button><button v-if="!contacts.length" form="contact-form" class="button primary" :disabled="busy">提交原因并查看</button></template></Modal>
  <Modal v-if="workId" title="记录人工跟进" @close="workId = ''"><form id="work-form" class="form-stack" @submit.prevent="resolveWork"><p class="muted">请如实记录实际协调结果。人工记录不会将失败邮件标记为已送达，也不会直接修改订单或库存。</p><label>处理说明<textarea v-model="workNote" required maxlength="500"/></label></form><template #footer><button class="button secondary" @click="workId = ''">返回</button><button form="work-form" class="button primary" :disabled="busy">保存处理记录</button></template></Modal>
  <OrdersView v-if="linkedOrderId" :key="linkedOrderId" :initial-order="linkedOrderId" dialog-only @close="closeLinkedOrder"/>
</template>
